fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Precondition: start + sub.len() <= main.len()
    for i in 0..sub.len() {
        if main[start + i] != sub[i] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // If sub is empty, it's always a subarray.
    if sub.is_empty() {
        return true;
    }

    // If sub is longer than main, cannot be a contiguous subarray.
    if sub.len() > main.len() {
        return false;
    }

    // Iterate over possible start indices
    let last_start = main.len() - sub.len();
    for start in 0..=last_start {
        if check_match_at(main, sub, start) {
            return true;
        }
    }

    false
}